"""Lexer and recursive-descent parser turning SQL text into a ``Query``.

Grammar and precedence are described in SPEC.md (the Syntax section).
The only public entry point is :func:`parse`.
"""

from typing import List, NamedTuple, Optional, Union

from .ast import (
    Between,
    Binary,
    Call,
    Column,
    Expr,
    In,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from .errors import QueryError

__all__ = ["parse"]

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

# Longest operators first so that "<=" wins over "<".
OPERATORS = ("<>", "<=", ">=", "!=", "||", "=", "<", ">", "+", "-", "*", "/",
             "(", ")", ",", ";")

COMPARISON_OPS = ("=", "!=", "<>", "<", "<=", ">", ">=")

# Token kinds
KEYWORD = "keyword"  # value: uppercased keyword
NAME = "name"        # value: name as written (quotes removed)
NUMBER = "number"    # value: int or float
STRING = "string"    # value: str
OP = "op"            # value: operator / punctuation text
EOF = "end of query"


class Token(NamedTuple):
    kind: str
    value: Union[str, int, float, None]
    start: int  # offset of the first character in the source
    end: int    # offset just past the last character

    def describe(self) -> str:
        if self.kind == EOF:
            return "end of query"
        if self.kind == STRING:
            return "string '%s'" % self.value
        if self.kind == NAME:
            return "name %r" % self.value
        if self.kind == KEYWORD:
            return "keyword %s" % self.value
        return repr(str(self.value)) if self.kind == OP else str(self.value)


def _is_name_start(ch: str) -> bool:
    return ch == "_" or ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _is_name_char(ch: str) -> bool:
    return _is_name_start(ch) or ch.isdigit() and ch.isascii()


def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def tokenize(sql: str) -> List[Token]:
    """Split ``sql`` into tokens, ending with an EOF token."""
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if ch.isspace():
            i += 1
        elif _is_name_start(ch):
            start = i
            while i < n and _is_name_char(sql[i]):
                i += 1
            word = sql[start:i]
            if word.upper() in KEYWORDS:
                tokens.append(Token(KEYWORD, word.upper(), start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
        elif _is_digit(ch) or (ch == "." and i + 1 < n and _is_digit(sql[i + 1])):
            start = i
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            if i < n and (_is_name_char(sql[i]) or sql[i] == "."):
                raise QueryError(
                    "invalid number %r at position %d"
                    % (sql[start:i + 1], start)
                )
            text = sql[start:i]
            value = float(text) if is_float else int(text)
            tokens.append(Token(NUMBER, value, start, i))
        elif ch == "'" or ch == '"':
            start = i
            value, i = _read_quoted(sql, i)
            kind = STRING if ch == "'" else NAME
            tokens.append(Token(kind, value, start, i))
        else:
            for op in OPERATORS:
                if sql.startswith(op, i):
                    tokens.append(Token(OP, op, i, i + len(op)))
                    i += len(op)
                    break
            else:
                raise QueryError(
                    "unexpected character %r at position %d" % (ch, i)
                )
    tokens.append(Token(EOF, None, n, n))
    return tokens


def _read_quoted(sql: str, i: int):
    """Read a quoted string or name starting at ``sql[i]`` (the quote).

    A doubled quote character stands for one quote. Returns the unescaped
    text and the offset just past the closing quote.
    """
    quote = sql[i]
    start = i
    i += 1
    parts = []
    while True:
        end = sql.find(quote, i)
        if end == -1:
            what = "string" if quote == "'" else "quoted name"
            raise QueryError(
                "unterminated %s starting at position %d" % (what, start)
            )
        parts.append(sql[i:end])
        if sql.startswith(quote * 2, end):
            parts.append(quote)
            i = end + 2
        else:
            return "".join(parts), end + 1


class Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers ---------------------------------------------------

    @property
    def current(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset: int = 1) -> Token:
        index = min(self.pos + offset, len(self.tokens) - 1)
        return self.tokens[index]

    def advance(self) -> Token:
        token = self.current
        if token.kind != EOF:
            self.pos += 1
        return token

    def at_keyword(self, *words: str) -> bool:
        return self.current.kind == KEYWORD and self.current.value in words

    def at_op(self, *ops: str) -> bool:
        return self.current.kind == OP and self.current.value in ops

    def accept_keyword(self, word: str) -> bool:
        if self.at_keyword(word):
            self.advance()
            return True
        return False

    def accept_op(self, op: str) -> bool:
        if self.at_op(op):
            self.advance()
            return True
        return False

    def expect_keyword(self, word: str) -> Token:
        if not self.at_keyword(word):
            self.error("expected %s" % word)
        return self.advance()

    def expect_op(self, op: str) -> Token:
        if not self.at_op(op):
            self.error("expected %r" % op)
        return self.advance()

    def expect_name(self, what: str = "a name") -> str:
        if self.current.kind != NAME:
            self.error("expected %s" % what)
        return self.advance().value

    def expect_unsigned_int(self, clause: str) -> int:
        token = self.current
        if token.kind != NUMBER or not isinstance(token.value, int):
            self.error("%s requires a non-negative integer" % clause)
        self.advance()
        return token.value

    def error(self, message: str):
        token = self.current
        raise QueryError(
            "syntax error: %s, but found %s at position %d"
            % (message, token.describe(), token.start)
        )

    # -- query -----------------------------------------------------------

    def parse_query(self) -> Query:
        if self.current.kind == EOF:
            raise QueryError("syntax error: empty query")
        self.expect_keyword("SELECT")
        distinct = self.accept_keyword("DISTINCT")
        columns = self.parse_columns()
        self.expect_keyword("FROM")
        table = self.expect_name("a table name")
        query = Query(distinct=distinct, columns=columns, table=table)

        if self.accept_keyword("WHERE"):
            query.where = self.parse_expr()
        if self.accept_keyword("GROUP"):
            self.expect_keyword("BY")
            query.group_by = self.parse_comma_list(self.parse_expr)
        if self.accept_keyword("HAVING"):
            query.having = self.parse_expr()
        if self.accept_keyword("ORDER"):
            self.expect_keyword("BY")
            query.order_by = self.parse_comma_list(self.parse_order_item)
        if self.accept_keyword("LIMIT"):
            query.limit = self.expect_unsigned_int("LIMIT")
            if self.accept_keyword("OFFSET"):
                query.offset = self.expect_unsigned_int("OFFSET")

        self.accept_op(";")
        if self.current.kind != EOF:
            self.error("expected end of query")
        return query

    def parse_comma_list(self, parse_item) -> list:
        items = [parse_item()]
        while self.accept_op(","):
            items.append(parse_item())
        return items

    def parse_columns(self) -> Optional[List[SelectItem]]:
        if self.accept_op("*"):
            return None
        return self.parse_comma_list(self.parse_select_item)

    def parse_select_item(self) -> SelectItem:
        start = self.current.start
        expr = self.parse_expr()
        end = self.tokens[self.pos - 1].end
        alias = None
        if self.accept_keyword("AS"):
            alias = self.expect_name("an alias after AS")
        elif self.current.kind == NAME:
            alias = self.advance().value
        return SelectItem(expr=expr, alias=alias, text=self.sql[start:end])

    def parse_order_item(self) -> OrderItem:
        expr = self.parse_expr()
        descending = False
        if self.accept_keyword("DESC"):
            descending = True
        else:
            self.accept_keyword("ASC")
        return OrderItem(expr=expr, descending=descending)

    # -- expressions, lowest precedence first ------------------------------

    def parse_expr(self) -> Expr:
        return self.parse_or()

    def parse_or(self) -> Expr:
        left = self.parse_and()
        while self.accept_keyword("OR"):
            left = Binary("OR", left, self.parse_and())
        return left

    def parse_and(self) -> Expr:
        left = self.parse_not()
        while self.accept_keyword("AND"):
            left = Binary("AND", left, self.parse_not())
        return left

    def parse_not(self) -> Expr:
        if self.accept_keyword("NOT"):
            return Unary("NOT", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self) -> Expr:
        left = self.parse_additive()

        if self.at_op(*COMPARISON_OPS):
            op = self.advance().value
            if op == "<>":
                op = "!="
            return Binary(op, left, self.parse_additive())

        if self.accept_keyword("IS"):
            negated = self.accept_keyword("NOT")
            self.expect_keyword("NULL")
            return IsNull(left, negated)

        negated = False
        if self.at_keyword("NOT"):
            nxt = self.peek()
            if nxt.kind == KEYWORD and nxt.value in ("IN", "BETWEEN", "LIKE"):
                self.advance()
                negated = True
            else:
                return left  # leave NOT for the caller to reject

        if self.accept_keyword("IN"):
            self.expect_op("(")
            items = self.parse_comma_list(self.parse_expr)
            self.expect_op(")")
            return In(left, items, negated)
        if self.accept_keyword("BETWEEN"):
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            return Between(left, low, high, negated)
        if self.accept_keyword("LIKE"):
            return Like(left, self.parse_additive(), negated)
        return left

    def parse_additive(self) -> Expr:
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            left = Binary(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self) -> Expr:
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = Binary(op, left, self.parse_unary())
        return left

    def parse_unary(self) -> Expr:
        if self.accept_op("-"):
            return Unary("-", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        token = self.current
        if token.kind == NUMBER or token.kind == STRING:
            self.advance()
            return Literal(token.value)
        if token.kind == KEYWORD and token.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return Literal({"NULL": None, "TRUE": True, "FALSE": False}[token.value])
        if token.kind == NAME:
            self.advance()
            is_bare = self.sql[token.start] != '"'
            if is_bare and self.at_op("("):
                return self.parse_call(token.value.upper())
            return Column(token.value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        self.error("expected an expression")

    def parse_call(self, name: str) -> Call:
        self.expect_op("(")
        if self.at_op("*"):
            if name != "COUNT":
                self.error("'*' is only allowed as the argument of COUNT")
            self.advance()
            self.expect_op(")")
            return Call(name, [], star=True)
        args = []
        if not self.at_op(")"):
            args = self.parse_comma_list(self.parse_expr)
        self.expect_op(")")
        return Call(name, args)


def parse(sql: str) -> Query:
    """Parse a SELECT statement into a :class:`minisql.ast.Query`.

    Raises :class:`minisql.errors.QueryError` on any syntax error.
    """
    return Parser(sql).parse_query()

